import React, { useState, useEffect } from 'react';

function Dashboard() {
  const [performance, setPerformance] = useState(null);
  const [loading, setLoading] = useState(true);
  const [history, setHistory] = useState([]);

  useEffect(() => {
    fetchPerformance();
    fetchHistory();
  }, []);

  const fetchPerformance = async () => {
    try {
      const response = await fetch('http://localhost:8000/api/performance');
      const data = await response.json();
      if (data.success) {
        setPerformance(data.performance);
      }
    } catch (error) {
      console.error('Error fetching performance:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchHistory = async () => {
    // Sample history data
    setHistory([
      { date: '2026-08-16', bets: 5, wins: 3, profit: 2450 },
      { date: '2026-08-15', bets: 8, wins: 4, profit: 1200 },
      { date: '2026-08-14', bets: 6, wins: 2, profit: -850 },
      { date: '2026-08-13', bets: 4, wins: 3, profit: 3200 },
    ]);
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="text-xl text-gray-600 dark:text-gray-400">Loading dashboard...</div>
      </div>
    );
  }

  const totalProfit = Object.values(performance || {}).reduce((acc, p) => acc + p.profit, 0);
  const totalWins = Object.values(performance || {}).reduce((acc, p) => acc + p.wins, 0);
  const totalBets = Object.values(performance || {}).reduce((acc, p) => acc + p.total, 0);
  const overallWinRate = totalBets > 0 ? Math.round((totalWins / totalBets) * 100) : 0;

  return (
    <div>
      <h1 className="text-3xl font-bold text-gray-800 dark:text-white mb-6">📊 Performance Dashboard</h1>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Total Bets</p>
          <p className="text-2xl font-bold text-gray-800 dark:text-white">{totalBets}</p>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Win Rate</p>
          <p className="text-2xl font-bold text-green-600 dark:text-green-400">{overallWinRate}%</p>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Total Profit</p>
          <p className={`text-2xl font-bold ${totalProfit >= 0 ? 'text-green-600' : 'text-red-600'}`}>
            {totalProfit >= 0 ? '+' : ''}{totalProfit} KES
          </p>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Active Days</p>
          <p className="text-2xl font-bold text-gray-800 dark:text-white">30</p>
        </div>
      </div>

      {/* Performance by Confidence */}
      <h2 className="text-2xl font-bold text-gray-700 dark:text-gray-300 mb-4">Performance by Confidence</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
        {performance && Object.entries(performance).map(([level, data]) => (
          <div key={level} className="bg-white dark:bg-gray-800 rounded-lg shadow p-4 border border-gray-200 dark:border-gray-700">
            <div className="flex justify-between items-center mb-2">
              <span className="font-bold text-gray-700 dark:text-gray-300">{level}</span>
              <span className={`text-xs px-2 py-1 rounded-full ${
                level === 'HIGH' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200' :
                level === 'MEDIUM' ? 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200' :
                'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200'
              }`}>
                {data.win_rate}%
              </span>
            </div>
            <div className="text-sm text-gray-600 dark:text-gray-400">
              <p>Bets: {data.total} | Wins: {data.wins}</p>
              <p className={data.profit >= 0 ? 'text-green-600' : 'text-red-600'}>
                Profit: {data.profit >= 0 ? '+' : ''}{data.profit} KES
              </p>
            </div>
          </div>
        ))}
      </div>

      {/* History */}
      <h2 className="text-2xl font-bold text-gray-700 dark:text-gray-300 mb-4">Recent History</h2>
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow overflow-hidden border border-gray-200 dark:border-gray-700">
        <table className="w-full">
          <thead className="bg-gray-100 dark:bg-gray-700">
            <tr>
              <th className="px-4 py-2 text-left text-sm font-medium text-gray-600 dark:text-gray-300">Date</th>
              <th className="px-4 py-2 text-left text-sm font-medium text-gray-600 dark:text-gray-300">Bets</th>
              <th className="px-4 py-2 text-left text-sm font-medium text-gray-600 dark:text-gray-300">Wins</th>
              <th className="px-4 py-2 text-left text-sm font-medium text-gray-600 dark:text-gray-300">Profit (KES)</th>
            </tr>
          </thead>
          <tbody>
            {history.map((item, index) => (
              <tr key={index} className="border-t border-gray-200 dark:border-gray-700">
                <td className="px-4 py-2 text-sm text-gray-800 dark:text-gray-200">{item.date}</td>
                <td className="px-4 py-2 text-sm text-gray-800 dark:text-gray-200">{item.bets}</td>
                <td className="px-4 py-2 text-sm text-gray-800 dark:text-gray-200">{item.wins}</td>
                <td className={`px-4 py-2 text-sm font-medium ${item.profit >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                  {item.profit >= 0 ? '+' : ''}{item.profit}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default Dashboard;
